#!/bin/bash
# Wrapper script to run commands with ulimit memory constraint
# This script is generated by setup_limits.sh and should not be edited manually.
#
# Usage:
#   ./scripts/run_with_ulimit.sh [command] [args...]

set -euo pipefail

# Memory limit in KB (7GB default)
MEMORY_LIMIT_KB=7168000

# Set virtual memory limit (in KB)
ulimit -v "${MEMORY_LIMIT_KB}"

# Check if the limit was set
CURRENT_LIMIT=$(ulimit -v)
if [[ "${CURRENT_LIMIT}" == "unlimited" ]]; then
    echo "WARNING: ulimit -v could not be set. Running without memory constraint."
    echo "This may happen if the script is not run with sufficient privileges or in a restricted environment."
else
    echo "INFO: Memory limit set to ${CURRENT_LIMIT} KB ($(( CURRENT_LIMIT / 1024 )) MB)"
fi

# Execute the command with all arguments
exec "$@"